begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,actor_id uuid,request_id uuid,connection_id uuid);
insert into fixture values(gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid());
insert into public.properties(id,org_id,name) select property_id,'22222222-2222-2222-2222-222222222222','ReviewFlow intake rollback fixture' from fixture;
create function pg_temp.manual_input(text_value text default 'Original review',source_id text default 'fixture-review') returns jsonb language sql as $$select jsonb_build_object('kind','manual','trigger','operator','reason','Reviewed source fixture','content',jsonb_build_object('platform','other','platformReviewId',source_id,'reviewText',text_value,'reviewerName','Fixture','rating',5)::text);$$;
create function pg_temp.normalized(id uuid) returns jsonb language plpgsql as $$declare r public.reviewflow_intake_requests;row jsonb;begin select * into r from public.reviewflow_intake_requests where reviewflow_intake_requests.id=normalized.id;row:=(r.raw_result->>'content')::jsonb;return jsonb_build_object('contractVersion','review-intake-v1','sourceHash',encode(extensions.digest(convert_to(r.raw_result->>'content','UTF8'),'sha256'),'hex'),'reviews',jsonb_build_array(row||jsonb_build_object('fingerprint',repeat('a',64),'legacyFingerprint',repeat('b',64),'identityBasis','provider_id','reviewDate',null,'reviewerAvatarUrl',null)),'duplicateRows',0,'retrievalMethod','manual','completeness','unknown');end$$;
create function pg_temp.preview(id uuid) returns jsonb language sql as $$select public.preview_reviewflow_intake(id,(select result_hash from public.reviewflow_intake_requests where reviewflow_intake_requests.id=preview.id),pg_temp.normalized(id));$$;
create function pg_temp.apply_input(id uuid) returns jsonb language sql as $$select jsonb_build_object('intakeId',id,'expectedVersion',(select version from public.reviewflow_intake_requests where reviewflow_intake_requests.id=apply_input.id),'reason','Reviewed all saved rows');$$;
create function pg_temp.control_input(id uuid,op text) returns jsonb language sql as $$select pg_temp.apply_input(id)||jsonb_build_object('operation',op);$$;
create function pg_temp.source_input() returns jsonb language sql as $$select jsonb_build_object('operation','save','connectionId',null,'expectedVersion',0,'platform','google','providerId','FixturePlaceID','sourceUrl','https://www.google.com/maps/place/fixture','method','api','frequency','hourly','replaceTarget',false,'reason','Reviewed fixture source')$$;

do $$declare f fixture;r jsonb;payload jsonb;command uuid:=gen_random_uuid();config_input jsonb:='{"expectedVersion":0,"defaultTone":"friendly","propertyPersonality":"Warm and clear","reason":"Reviewed response preferences"}';begin select * into f from fixture;
 perform pg_temp.check(not has_table_privilege('authenticated','public.review_platform_connections','select') and not has_table_privilege('authenticated','public.review_platform_connections','update'),'browser cannot read source credentials or mutate connections');
 perform pg_temp.check(not has_table_privilege('authenticated','public.reviewflow_config','update') and not has_table_privilege('authenticated','public.reviews','update'),'browser cannot bypass recorded settings or source decisions');
 perform pg_temp.check(not has_function_privilege('authenticated','public.begin_reviewflow_intake(uuid,uuid,uuid,jsonb,jsonb)','execute') and not has_table_privilege('authenticated','public.reviewflow_intake_requests','select'),'raw receipts and intake commands are server-private');
 perform pg_temp.check(public.decide_reviewflow_configuration(command,f.property_id,gen_random_uuid(),config_input)->>'state'='manager_required','unknown operator cannot change preferences');
 perform pg_temp.check(public.decide_reviewflow_configuration(command,f.property_id,f.actor_id,config_input)->>'state'='saved' and public.decide_reviewflow_configuration(command,f.property_id,f.actor_id,config_input)->>'state'='replayed','saved configuration recovers one exact decision');
 perform pg_temp.check(public.decide_reviewflow_configuration(gen_random_uuid(),f.property_id,f.actor_id,config_input)->>'state'='stale_configuration','stale preference edits are rejected');
 perform pg_temp.check((select default_tone='friendly' and not is_active and not auto_respond_positive from public.reviewflow_config where property_id=f.property_id),'preferences cannot activate legacy automatic publication');
 payload:=pg_temp.source_input();r:=public.decide_reviewflow_connection(f.connection_id,f.property_id,f.actor_id,payload);
 perform pg_temp.check(r->>'state'='saved' and public.decide_reviewflow_connection(f.connection_id,f.property_id,f.actor_id,payload)->>'state'='replayed','source save has stable decision identity');
 perform pg_temp.check((select scheduled_by=f.actor_id and last_sync_at is null from public.review_platform_connections where id=f.connection_id),'source setup saves scheduling authority without claiming successful sync');
 update public.review_platform_connections set access_token='fixture-private-access',refresh_token='fixture-private-refresh',api_key='fixture-private-key' where id=f.connection_id;
 payload:=payload||jsonb_build_object('connectionId',f.connection_id,'expectedVersion',(select version from public.review_platform_connections where id=f.connection_id),'providerId','DifferentFixture');
 perform pg_temp.check(public.decide_reviewflow_connection(gen_random_uuid(),f.property_id,f.actor_id,payload)->>'state'='replacement_review_required','changed source target requires explicit review');
 r:=public.decide_reviewflow_connection(gen_random_uuid(),f.property_id,f.actor_id,payload||'{"replaceTarget":true}');
 perform pg_temp.check(r->>'state'='saved' and(select access_token='fixture-private-access' and refresh_token='fixture-private-refresh' and api_key='fixture-private-key' from public.review_platform_connections where id=f.connection_id),'settings saves preserve omitted server credentials');
 perform pg_temp.check(not exists(select 1 from public.reviewflow_connection_revisions where property_id=f.property_id and (after_state::text like '%fixture-private%' or before_state::text like '%fixture-private%')),'private source revision metadata excludes credentials');
 payload:=pg_temp.manual_input();
 perform pg_temp.check(public.begin_reviewflow_intake(f.request_id,f.property_id,gen_random_uuid(),payload,'{}')->>'state'='forbidden','foreign operator cannot save source evidence');
 perform pg_temp.check(public.begin_reviewflow_intake(f.request_id,f.property_id,f.actor_id,payload,'{}')->>'state'='result_ready','manual source receipt is saved before parsing');
 perform pg_temp.check(not exists(select 1 from public.reviews where property_id=f.property_id),'saving a source cannot mutate reviews');
 perform pg_temp.check(public.begin_reviewflow_intake(f.request_id,f.property_id,f.actor_id,payload,'{}')->>'state'='result_ready','lost source acknowledgement recovers saved receipt');
 perform pg_temp.check(public.begin_reviewflow_intake(f.request_id,f.property_id,f.actor_id,pg_temp.manual_input('Changed'),'{}')->>'state'='request_conflict','same source decision cannot change content');
 perform pg_temp.check(public.preview_reviewflow_intake(f.request_id,'wrong',pg_temp.normalized(f.request_id))->>'state'='result_conflict','preview requires exact saved receipt');
 r:=pg_temp.preview(f.request_id);perform pg_temp.check(r->>'state'='preview','validated manual source becomes a saved preview');
 perform pg_temp.check((select preview->0->>'changeKind'='inserted' from public.reviewflow_intake_requests where id=f.request_id),'preview describes new review without inserting it');
 perform pg_temp.check((select actor_id is null and service_principal='reviewflow.intake' from public.shared_action_events where property_id=f.property_id and action='review.intake.previewed'),'worker preview has an explicit system principal');
 command:=gen_random_uuid();payload:=pg_temp.apply_input(f.request_id);
 perform pg_temp.check(public.apply_reviewflow_intake(command,f.property_id,f.actor_id,payload)->>'state'='saved' and public.apply_reviewflow_intake(command,f.property_id,f.actor_id,payload)->>'state'='replayed','applying a saved preview is idempotent after lost reply');
 perform pg_temp.check((select count(*)=1 from public.reviews where property_id=f.property_id) and(select count(*)=1 from public.reputation_cases where property_id=f.property_id),'review and case are created together once');
 perform pg_temp.check((select count(*)=1 from public.reviewflow_intake_observations where request_id=f.request_id),'applied source has immutable private observation evidence');
 perform pg_temp.check((select actor_id=f.actor_id and service_principal is null from public.shared_action_events where property_id=f.property_id and action='review.intake.applied'),'human import application is separate from system parsing');
 begin update public.reviewflow_intake_requests set raw_result='{}' where id=f.request_id;raise exception 'FAIL replace receipt';exception when raise_exception then if SQLERRM<>'The source receipt cannot be replaced' then raise;end if;end;
 perform pg_temp.check(true,'saved source receipt is immutable');
end$$;

do $$declare f fixture;run_id uuid:=gen_random_uuid();second uuid:=gen_random_uuid();rebased uuid:=gen_random_uuid();payload jsonb;r jsonb;review_id uuid;begin select * into f from fixture;
 perform public.begin_reviewflow_intake(run_id,f.property_id,f.actor_id,pg_temp.manual_input('Corrected review'),'{}');perform pg_temp.preview(run_id);
 perform pg_temp.check((select preview->0->>'changeKind'='updated' from public.reviewflow_intake_requests where reviewflow_intake_requests.id=run_id),'changed source preview identifies exact existing review');
 select reviews.id into review_id from public.reviews where property_id=f.property_id;
 update public.reviews set review_text='A newer source arrived',sentiment='positive',response_status='responded' where reviews.id=review_id;
 r:=public.apply_reviewflow_intake(gen_random_uuid(),f.property_id,f.actor_id,pg_temp.apply_input(run_id));
 perform pg_temp.check(r->>'state'='held' and(select review_text='A newer source arrived' from public.reviews where reviews.id=review_id),'stale preview cannot overwrite a newer review');
 perform pg_temp.check((select response_status='pending' and sentiment is null from public.reviews where reviews.id=review_id),'new source clears current approval and analysis status');
 perform pg_temp.check(public.control_reviewflow_intake(rebased,f.property_id,f.actor_id,pg_temp.control_input(run_id,'rebase'))->>'state'='saved','explicit rebase reuses a saved receipt');
 perform pg_temp.check((select raw_result=(select raw_result from public.reviewflow_intake_requests where reviewflow_intake_requests.id=run_id) and parent_request_id=run_id and claim_token is null from public.reviewflow_intake_requests where reviewflow_intake_requests.id=rebased),'rebasing never creates another provider fetch');
 perform pg_temp.preview(rebased);perform public.apply_reviewflow_intake(gen_random_uuid(),f.property_id,f.actor_id,pg_temp.apply_input(rebased));
 perform pg_temp.check((select review_text='Corrected review' and source_version=3 from public.reviews where reviews.id=review_id),'reviewed rebuilt preview applies its exact correction');
 perform public.begin_reviewflow_intake(second,f.property_id,f.actor_id,pg_temp.manual_input('Corrected review'),'{}');perform pg_temp.preview(second);perform public.apply_reviewflow_intake(gen_random_uuid(),f.property_id,f.actor_id,pg_temp.apply_input(second));
 perform pg_temp.check((select summary->>'unchanged'='1' from public.reviewflow_intake_requests where reviewflow_intake_requests.id=second),'repeat observation is reported unchanged');
 perform pg_temp.check((select source_version=3 from public.reviews where reviews.id=review_id),'unchanged observation does not invalidate source approvals');
end$$;

do $$declare f fixture;run_id uuid:=gen_random_uuid();input jsonb;fetch_input jsonb;claim jsonb;receipt jsonb;command uuid:=gen_random_uuid();source public.review_platform_connections;due jsonb;begin select * into f from fixture;select * into source from public.review_platform_connections where review_platform_connections.id=f.connection_id;
 input:=jsonb_build_object('kind','source','trigger','operator','connectionId',source.id,'connectionVersion',source.version,'reason','Reviewed source check');fetch_input:=jsonb_build_object('contractVersion','review-intake-v1','platform','google','providerId',source.place_id,'method','api','url','https://example.invalid/scraper/google-reviews','body',jsonb_build_object('place_id',source.place_id,'max_reviews',50));
 perform pg_temp.check(public.begin_reviewflow_intake(run_id,f.property_id,f.actor_id,input,fetch_input)->>'state'='queued','source fetch intent is saved first');
 perform pg_temp.check(public.begin_reviewflow_intake(gen_random_uuid(),f.property_id,f.actor_id,input,fetch_input)->>'state'='busy','one unfinished check per source');
 claim:=public.claim_reviewflow_intake(run_id);perform pg_temp.check(claim->>'state'='invoke_once' and public.claim_reviewflow_intake(run_id)->>'state'='running','a source fetch can be claimed exactly once');
 perform pg_temp.check((select last_sync_at is null from public.review_platform_connections where review_platform_connections.id=source.id),'fetch claim does not claim a successful sync');
 receipt:=jsonb_build_object('status','received','httpStatus',200,'content','{"success":true,"reviews":[]}','receivedAt',clock_timestamp());
 perform pg_temp.check(public.record_reviewflow_intake_result(run_id,gen_random_uuid(),receipt)->>'state'='claim_mismatch','wrong execution cannot attach a receipt');
 perform pg_temp.check(public.record_reviewflow_intake_result(run_id,(claim->>'claimToken')::uuid,receipt)->>'state'='saved' and public.record_reviewflow_intake_result(run_id,(claim->>'claimToken')::uuid,receipt)->>'state'='replayed','receipt persistence retry does not fetch again');
 perform pg_temp.check(public.record_reviewflow_intake_result(run_id,(claim->>'claimToken')::uuid,receipt||'{"content":"changed"}')->>'state'='result_conflict','source receipt cannot be substituted');
 perform public.preview_reviewflow_intake(run_id,(select result_hash from public.reviewflow_intake_requests where reviewflow_intake_requests.id=run_id),jsonb_build_object('contractVersion','review-intake-v1','reviews','[]'::jsonb,'sourceHash',encode(extensions.digest(convert_to(receipt->>'content','UTF8'),'sha256'),'hex'),'retrievalMethod','provider_api','completeness','sample','duplicateRows',0));
 perform pg_temp.check(public.apply_reviewflow_intake(command,f.property_id,f.actor_id,pg_temp.apply_input(run_id))->>'state'='saved','confirmed empty sample is an honest successful source check');
 perform pg_temp.check((select last_sync_at is not null and total_reviews_synced=0 from public.review_platform_connections where review_platform_connections.id=source.id),'confirmed source health changes only after application');
 run_id:=gen_random_uuid();perform public.begin_reviewflow_intake(run_id,f.property_id,f.actor_id,input,fetch_input);claim:=public.claim_reviewflow_intake(run_id);
 perform public.control_reviewflow_intake(gen_random_uuid(),f.property_id,f.actor_id,pg_temp.control_input(run_id,'stop'));perform public.record_reviewflow_intake_result(run_id,(claim->>'claimToken')::uuid,receipt);
 perform pg_temp.check((select state='stopped' and raw_result=receipt from public.reviewflow_intake_requests where reviewflow_intake_requests.id=run_id),'late source receipt is retained after stop without applying');
 due:=public.list_reviewflow_due_sources(50);perform pg_temp.check(exists(select 1 from jsonb_array_elements(due) d where d->>'id'=source.id::text),'reviewed scheduled source is discoverable');
 input:=input||jsonb_build_object('trigger','schedule','scheduleKey',(select d->>'schedule_key' from jsonb_array_elements(due) d where d->>'id'=source.id::text));
 claim:=public.begin_reviewflow_intake(gen_random_uuid(),f.property_id,null,input,fetch_input);run_id:=(claim->>'requestId')::uuid;
 perform pg_temp.check(claim->>'state'='queued' and(select actor_id is null and trigger_kind='schedule' from public.reviewflow_intake_requests where reviewflow_intake_requests.id=run_id),'scheduled request uses a system principal with reviewed authority');
 perform pg_temp.check(public.begin_reviewflow_intake(gen_random_uuid(),f.property_id,null,input,fetch_input)->>'requestId'=run_id::text,'concurrent schedule ticks reuse the exact bucket identity');
 perform pg_temp.check(not exists(select 1 from jsonb_array_elements(public.list_reviewflow_due_sources(50)) d where d->>'id'=source.id::text),'unfinished scheduled check is not selected repeatedly');
 perform public.decide_reviewflow_connection(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('operation','disconnect','connectionId',source.id,'expectedVersion',source.version,'reason','Stop fixture source access'));
 perform pg_temp.check(public.claim_reviewflow_intake(run_id)->>'state'='held','disconnect fences previously queued scheduled work');
 perform pg_temp.check((select not is_active and scheduled_by is null from public.review_platform_connections where review_platform_connections.id=source.id),'disconnect removes future scheduling authority');
end$$;

do $$declare f fixture;run_id uuid:=gen_random_uuid();command uuid:=gen_random_uuid();r jsonb;begin select * into f from fixture;
 perform public.begin_reviewflow_intake(run_id,f.property_id,f.actor_id,pg_temp.manual_input('New isolated review','atomic-fixture'),'{}');perform pg_temp.preview(run_id);
 perform public.append_shared_action_event(command,command,f.property_id,f.actor_id,'reviewflow','review.intake.applied','server_confirmed','succeeded','{"conflict":true}',null,null,'{}','{}');
 begin perform public.apply_reviewflow_intake(command,f.property_id,f.actor_id,pg_temp.apply_input(run_id));raise exception 'FAIL activity atomicity';exception when raise_exception then if SQLERRM<>'Review decision history could not be saved' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.reviews where property_id=f.property_id and platform_review_id='atomic-fixture') and not exists(select 1 from public.reviewflow_intake_observations where request_id=run_id),'failed semantic activity rolls back review, case and source evidence together');
 perform pg_temp.check((select state='preview' from public.reviewflow_intake_requests where reviewflow_intake_requests.id=run_id) and not exists(select 1 from public.reviewflow_commands where reviewflow_commands.id=command),'failed activity preserves the recoverable preview');
end$$;
select count(*) as passed_assertions from checks;
rollback;
